<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $start=trim((string)($_GET['start']??date('Y-m-01'))); $end=trim((string)($_GET['end']??date('Y-m-d'))); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start=date('Y-m-01'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end=date('Y-m-d'); if($start>$end){$t=$start;$start=$end;$end=$t;} $from=$start.' 00:00:00'; $to=date('Y-m-d',strtotime($end.' +1 day')).' 00:00:00'; $one=function(string $sql)use($db,$from,$to){$q=$db->prepare($sql);$q->execute([$from,$to]);return (float)$q->fetchColumn();}; $sales=$one('SELECT COALESCE(SUM(total),0) FROM sales WHERE created_at>=? AND created_at<?'); $collected=$one('SELECT COALESCE(SUM(paid),0) FROM sales WHERE created_at>=? AND created_at<?'); $purchases=$one('SELECT COALESCE(SUM(subtotal),0) FROM purchases WHERE created_at>=? AND created_at<?'); $purchasePaid=$one('SELECT COALESCE(SUM(paid),0) FROM purchases WHERE created_at>=? AND created_at<?'); $expenses=$one('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE created_at>=? AND created_at<?'); $saleReturns=$one("SELECT COALESCE(SUM(amount),0) FROM returns WHERE return_type='sale' AND created_at>=? AND created_at<?"); $purchaseReturns=$one("SELECT COALESCE(SUM(amount),0) FROM returns WHERE return_type='purchase' AND created_at>=? AND created_at<?"); $cogs=$one('SELECT COALESCE(SUM(si.quantity_units*COALESCE(b.purchase_unit_cost,m.purchase_price)),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN medicines m ON m.id=si.medicine_id LEFT JOIN batches b ON b.id=si.batch_id WHERE s.created_at>=? AND s.created_at<?'); $netSales=max(0,$sales-$saleReturns); $netPurchases=max(0,$purchases-$purchaseReturns); $grossProfit=$netSales-$cogs; $netProfit=$grossProfit-$expenses; $customerDue=(float)$db->query("SELECT COALESCE(SUM(total-paid),0) FROM sales WHERE payment_method='credit' AND total>paid")->fetchColumn(); $supplierDue=(float)$db->query('SELECT COALESCE(SUM(subtotal-paid),0) FROM purchases WHERE subtotal>paid')->fetchColumn(); $low=$db->query("SELECT m.name,m.reorder_level,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id HAVING stock<=m.reorder_level ORDER BY stock")->fetchAll(); $expiry=$db->query("SELECT m.name,b.batch_no,b.expiry_date,b.units_remaining FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.expiry_date IS NOT NULL AND b.expiry_date<=DATE_ADD(CURDATE(),INTERVAL 90 DAY) AND b.units_remaining>0 ORDER BY b.expiry_date")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="style.css"><style>.report-wrap{max-width:1400px;margin:auto}.report-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:24px}.report-hero h1{font-size:34px;margin:4px 0}.report-hero p{margin:0;color:#64748b}.filters{display:flex;gap:10px;align-items:end;background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:14px;box-shadow:0 4px 18px rgba(15,23,42,.05)}.filters label{font-size:12px;font-weight:700;color:#64748b}.filters input{display:block;margin-top:5px}.filters .btn{height:40px}.kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:16px}.kpi{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:20px;box-shadow:0 5px 20px rgba(15,23,42,.05)}.kpi small{display:block;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.06em;font-size:11px}.kpi strong{display:block;font-size:25px;margin-top:9px}.kpi span{display:block;color:#94a3b8;font-size:12px;margin-top:5px}.primary{border-left:4px solid #2563eb}.success{border-left:4px solid #16a34a}.warn{border-left:4px solid #f59e0b}.danger{border-left:4px solid #dc2626}.profit-card{background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;border-radius:20px;padding:24px;margin:22px 0;display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:20px;box-shadow:0 10px 30px rgba(15,23,42,.18)}.profit-card small{color:#cbd5e1;text-transform:uppercase;font-size:11px;font-weight:700}.profit-card strong{display:block;font-size:30px;margin-top:8px}.profit-card .sub{color:#cbd5e1;font-size:13px;margin-top:4px}.report-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.report-panel{background:#fff;border:1px solid #e2e8f0;border-radius:18px;overflow:hidden;box-shadow:0 5px 20px rgba(15,23,42,.05)}.report-panel h2{font-size:17px;margin:0;padding:18px 20px;border-bottom:1px solid #e2e8f0}.report-panel .table-wrap{overflow:auto}.report-panel table{width:100%;border-collapse:collapse}.report-panel th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc;padding:12px 16px;text-align:left}.report-panel td{padding:13px 16px;border-top:1px solid #f1f5f9}.empty{padding:24px;color:#64748b;text-align:center}.section-title{margin:28px 0 14px;font-size:20px}@media(max-width:1000px){.kpi-grid{grid-template-columns:repeat(2,1fr)}.report-hero{align-items:stretch;flex-direction:column}.filters{flex-wrap:wrap}.profit-card{grid-template-columns:1fr}.report-grid{grid-template-columns:1fr}}@media(max-width:600px){.kpi-grid{grid-template-columns:1fr}.filters{display:grid;grid-template-columns:1fr}.report-hero h1{font-size:28px}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main class="report-wrap"><div class="report-hero"><div><div class="eyebrow">BUSINESS INTELLIGENCE</div><h1>Reports & Analytics</h1><p>Track sales, purchasing, profitability, cash flow and stock health.</p></div><form method="get" class="filters"><label>From<input type="date" name="start" value="<?=e($start)?>"></label><label>To<input type="date" name="end" value="<?=e($end)?>"></label><button class="btn">Apply</button></form></div><div class="kpi-grid"><div class="kpi primary"><small>Gross Sales</small><strong>Rs. <?=money($sales)?></strong><span>Before customer returns</span></div><div class="kpi success"><small>Net Sales</small><strong>Rs. <?=money($netSales)?></strong><span>After customer returns</span></div><div class="kpi warn"><small>Purchases</small><strong>Rs. <?=money($netPurchases)?></strong><span>After supplier returns</span></div><div class="kpi success"><small>Collected</small><strong>Rs. <?=money($collected)?></strong><span>Payments received</span></div></div><div class="profit-card"><div><small>Net Profit</small><strong>Rs. <?=money($netProfit)?></strong><div class="sub">Gross profit minus operating expenses</div></div><div><small>Gross Profit</small><strong>Rs. <?=money($grossProfit)?></strong><div class="sub">Net sales minus estimated COGS</div></div><div><small>Expenses</small><strong>Rs. <?=money($expenses)?></strong><div class="sub">Operating expenses for this period</div></div></div><div class="kpi-grid"><div class="kpi danger"><small>Customer Due</small><strong>Rs. <?=money($customerDue)?></strong><span>Outstanding credit sales</span></div><div class="kpi warn"><small>Supplier Due</small><strong>Rs. <?=money($supplierDue)?></strong><span>Outstanding purchases</span></div><div class="kpi"><small>Customer Returns</small><strong>Rs. <?=money($saleReturns)?></strong><span>Returned sales</span></div><div class="kpi"><small>Supplier Returns</small><strong>Rs. <?=money($purchaseReturns)?></strong><span>Returned purchases</span></div></div><h2 class="section-title">Inventory Alerts</h2><div class="report-grid"><section class="report-panel"><h2>⚠️ Low Stock</h2><div class="table-wrap"><table><tr><th>Medicine</th><th>Stock</th><th>Reorder</th></tr><?php if(!$low):?><tr><td colspan="3" class="empty">✓ No low-stock medicines</td></tr><?php else:foreach($low as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=number_format((float)$r['stock'])?></td><td><?=number_format((float)$r['reorder_level'])?></td></tr><?php endforeach;endif;?></table></div></section><section class="report-panel"><h2>⏰ Expiring Within 90 Days</h2><div class="table-wrap"><table><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Units</th></tr><?php if(!$expiry):?><tr><td colspan="4" class="empty">✓ No upcoming expiries</td></tr><?php else:foreach($expiry as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['batch_no']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=number_format((float)$r['units_remaining'])?></td></tr><?php endforeach;endif;?></table></div></section></div></main></body></html>